class Counter:
 def __init__(self,value=0): self.value=value
 def apply_many(self,deltas,limit):
  for delta in deltas:
   self.value += delta
   if not isinstance(delta,int) or isinstance(delta,bool): raise TypeError('delta')
   if not 0 <= self.value <= limit: raise ValueError('range')
  return self.value

