class Cache:
 def __init__(self,clock): self.clock=clock; self.data={}
 def set(self,key,value,ttl): self.data[key]=(value,self.clock()+ttl)
 def get(self,key,default=None):
  value,expires=self.data.get(key,(default,0))
  if self.clock()>expires: return default
  return value

